style:
/* 青岚 —— 灰绿卡片式分栏 + 圆徽标题 + 英文副名 */

.tw-qinglan.resume-paper {
  background: #ffffff;
  color: #2b3630;
}

/* 页眉：整块浅灰信息卡，照片居左，姓名上方一行英文标签 */
.tw-qinglan.resume-paper .paper-header {
  margin: 0 0 3mm;
  padding: 5.6mm 6mm 5mm;
  border: none;
  border-radius: 3.2mm;
  background: #f1f2f0;
  print-color-adjust: exact;
}

.tw-qinglan.resume-paper .paper-header--photo {
  align-items: flex-start;
  gap: 6.5mm;
}

.tw-qinglan.resume-paper .paper-header__main {
  display: block;
  flex: 1 1 auto;
  min-width: 0;
}

.tw-qinglan.resume-paper .paper-name-row {
  display: block;
}

.tw-qinglan.resume-paper .paper-name-row::before {
  content: "PERSONAL RESUME / 个人简历";
  display: block;
  margin-bottom: 2.2mm;
  color: #26332c;
  font-size: calc(var(--paper-base-size) * 0.92);
  font-weight: 700;
  letter-spacing: 0.16em;
}

.tw-qinglan.resume-paper .paper-name {
  display: inline-block;
  color: #1f2b26;
  font-size: calc(var(--paper-base-size) * 2.3);
  font-weight: 700;
  letter-spacing: 0.02em;
  line-height: 1.3;
}

.tw-qinglan.resume-paper .paper-identity {
  display: inline-block;
  margin-left: 2.4mm;
  padding: 0;
  border: none;
  border-radius: 0;
  color: #7d8a84;
  font-size: calc(var(--paper-base-size) * 0.88);
}

.tw-qinglan.resume-paper .paper-role {
  margin-top: 2.4mm;
  color: #3c4a44;
  font-size: calc(var(--paper-base-size) * 0.92);
  font-weight: 600;
}

.tw-qinglan.resume-paper .paper-role::before {
  content: "意向岗位：";
  color: #7d8a84;
  font-weight: 400;
}

.tw-qinglan.resume-paper .paper-contacts--labeled {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 1mm 8mm;
  margin-top: 3.2mm;
  padding: 0;
  border: none;
  color: #33403a;
  font-size: calc(var(--paper-base-size) * 0.88);
}

.tw-qinglan.resume-paper .paper-contact {
  display: flex;
  gap: 1.6mm;
  min-width: 0;
}

.tw-qinglan.resume-paper .paper-contact + .paper-contact::before {
  display: none;
}

.tw-qinglan.resume-paper .paper-contact__label {
  flex: 0 0 auto;
  color: #7d8a84;
}

.tw-qinglan.resume-paper .paper-photo {
  order: -1;
  width: 23mm;
  height: 31mm;
  border: 1mm solid #ffffff;
  border-radius: 2mm;
  object-fit: cover;
  box-shadow: 0 1.6mm 5mm -2.6mm rgba(47, 66, 57, 0.32);
  print-color-adjust: exact;
}

.tw-qinglan.resume-paper .paper-photo--monogram {
  display: grid;
  place-items: center;
  width: 23mm;
  height: 23mm;
  border: 1mm solid #ffffff;
  border-radius: 50%;
  background: #e3eee7;
  color: #4f7f68;
  font-size: calc(var(--paper-base-size) * 1.8);
  font-weight: 600;
}

/* 每个模块是一张浅色圆角卡片 */
.tw-qinglan.resume-paper .paper-section {
  margin: 0 0 3mm;
  padding: 3.4mm 4.2mm 4mm;
  border: 1px solid #e6ebe3;
  border-radius: 3.2mm;
  background: #f6f8f5;
  print-color-adjust: exact;
}

.tw-qinglan.resume-paper .paper-section:last-child {
  margin-bottom: 0;
}

/* 模块标题：浅绿圆徽 + 中文粗体 + 英文副名 */
.tw-qinglan.resume-paper .paper-style-icon .paper-section__title {
  display: flex;
  align-items: center;
  gap: 2.6mm;
  margin: 0 0 2.8mm;
  color: #26332c;
  font-size: calc(var(--paper-base-size) * 1.08);
  font-weight: 700;
  letter-spacing: 0.02em;
}

.tw-qinglan.resume-paper .paper-style-icon .paper-section__icon {
  display: grid;
  flex: 0 0 auto;
  place-items: center;
  width: 5.6mm;
  height: 5.6mm;
  border: none;
  border-radius: 50%;
  background: #dcebe1;
  color: #3f6b56;
  print-color-adjust: exact;
}

.tw-qinglan.resume-paper .paper-style-icon .paper-section__icon svg {
  width: 54%;
  height: 54%;
}

.tw-qinglan.resume-paper .paper-style-icon .paper-section__title::before {
  order: 2;
  margin-left: 0.6mm;
  color: #8fa39a;
  font-size: calc(var(--paper-base-size) * 0.78);
  font-weight: 400;
  letter-spacing: 0.08em;
}

.tw-qinglan.resume-paper .paper-style-icon .paper-section__title::after {
  display: none;
}

.tw-qinglan.resume-paper .is-job_intention .paper-section__title::before {
  content: "Intention";
}

.tw-qinglan.resume-paper .is-education .paper-section__title::before {
  content: "Education";
}

.tw-qinglan.resume-paper .is-work_experience .paper-section__title::before {
  content: "Experience";
}

.tw-qinglan.resume-paper .is-project_experience .paper-section__title::before {
  content: "Projects";
}

.tw-qinglan.resume-paper .is-campus_experience .paper-section__title::before {
  content: "Campus";
}

.tw-qinglan.resume-paper .is-skills_summary .paper-section__title::before {
  content: "Skills";
}

.tw-qinglan.resume-paper .is-skill_proficiency .paper-section__title::before {
  content: "Proficiency";
}

.tw-qinglan.resume-paper .is-self_evaluation .paper-section__title::before {
  content: "Summary";
}

.tw-qinglan.resume-paper .is-paper_publication .paper-section__title::before {
  content: "Papers";
}

.tw-qinglan.resume-paper .is-portfolio .paper-section__title::before {
  content: "Portfolio";
}

.tw-qinglan.resume-paper .is-postgraduate_info .paper-section__title::before {
  content: "Postgraduate";
}

.tw-qinglan.resume-paper .is-competition .paper-section__title::before {
  content: "Contest";
}

.tw-qinglan.resume-paper .is-award .paper-section__title::before {
  content: "Awards";
}

.tw-qinglan.resume-paper .is-certificate .paper-section__title::before {
  content: "Certificates";
}

.tw-qinglan.resume-paper .is-journal_paper .paper-section__title::before {
  content: "Journals";
}

.tw-qinglan.resume-paper .is-hobby .paper-section__title::before {
  content: "Interests";
}

/* 求职意向：回到正文那套浅绿卡片，岗位做主语，城市 / 薪资 / 状态收成三枚标签 */
.tw-qinglan.resume-paper .is-job_intention {
  padding: 3.2mm 4.2mm 3.6mm;
  border-color: #dfeae0;
  background: #eef4ef;
}

.tw-qinglan.resume-paper .is-job_intention .paper-section__title {
  margin-bottom: 2.6mm;
}

/* 两层包裹拆成 contents，岗位和三枚标签才排在同一条基线上，放不下时整体换行。 */
.tw-qinglan.resume-paper .is-job_intention .paper-item-head,
.tw-qinglan.resume-paper .is-job_intention .paper-item-sub {
  display: contents;
}

.tw-qinglan.resume-paper .is-job_intention .paper-item {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 2mm 3mm;
}

.tw-qinglan.resume-paper .is-job_intention .paper-item-title {
  position: relative;
  padding-left: 3.4mm;
  color: #1f2b26;
  font-size: calc(var(--paper-base-size) * 1.16);
  font-weight: 700;
}

.tw-qinglan.resume-paper .is-job_intention .paper-item-title::before {
  content: "";
  position: absolute;
  top: 0.5mm;
  bottom: 0.5mm;
  left: 0;
  width: 1.1mm;
  border-radius: 1mm;
  background: #4f7f68;
  print-color-adjust: exact;
}

.tw-qinglan.resume-paper .is-job_intention .paper-item-period,
.tw-qinglan.resume-paper .is-job_intention .paper-item-sub span {
  padding: 0.8mm 3.2mm;
  border: 1px solid #cfe0d3;
  border-radius: 999px;
  background: #ffffff;
  color: #3f6b56;
  font-size: calc(var(--paper-base-size) * 0.86);
  font-weight: 500;
  line-height: 1.5;
  white-space: nowrap;
  print-color-adjust: exact;
}

/* 条目：标题深色、日期浅灰、专业 / 职位用主题绿 */
.tw-qinglan.resume-paper .paper-item-title {
  color: #22302a;
  font-weight: 700;
}

.tw-qinglan.resume-paper .paper-item-period {
  color: #6d7a73;
  font-size: calc(var(--paper-base-size) * 0.9);
  font-weight: 400;
}

.tw-qinglan.resume-paper .paper-item-sub {
  color: #4f7f68;
  font-weight: 600;
}

.tw-qinglan.resume-paper .paper-item-sub span + span::before {
  content: " | ";
  margin-right: 0;
  color: #c6d1ca;
}

.tw-qinglan.resume-paper .paper-item-tag {
  color: #4f7f68;
}

/* 正文细节 */
.tw-qinglan.resume-paper .paper-note {
  color: #5f6b64;
}

.tw-qinglan.resume-paper .paper-note__tag {
  padding: 0;
  border: none;
  border-radius: 0;
  background: transparent;
  color: #4f7f68;
  font-weight: 600;
}

.tw-qinglan.resume-paper .paper-meta-line {
  color: #6d7a73;
  font-size: calc(var(--paper-base-size) * 0.88);
}

.tw-qinglan.resume-paper .paper-rich {
  color: #3f4c45;
}

.tw-qinglan.resume-paper .paper-rich li {
  margin: 0.5mm 0;
}

.tw-qinglan.resume-paper .paper-rich li::marker {
  color: #8aa79a;
}

.tw-qinglan.resume-paper .paper-skill {
  border-bottom: 1px solid #e6ebe3;
}

.tw-qinglan.resume-paper .paper-skill__name {
  color: #2b3630;
  font-weight: 600;
}

.tw-qinglan.resume-paper .paper-skill__dots {
  display: none;
}

.tw-qinglan.resume-paper .paper-skill__level {
  display: inline;
  color: #6d7a73;
  font-size: calc(var(--paper-base-size) * 0.86);
}

.tw-qinglan.resume-paper .paper-footer {
  margin-top: 6mm;
  padding-top: 2.4mm;
  border-top: 1px solid #e6ebe3;
  color: #9aa79f;
}

/* 标签之间靠留白分开就够，通用条目那套竖线分隔符在这里会多出一笔。 */
.tw-qinglan.resume-paper .is-job_intention .paper-item-sub span + span::before {
  content: none;
}
